extends "res://htd/htd_test.gd"

func _run_tests() -> void:
	var scene := await instantiate_scene("res://enemy.tscn")
	if not check("enemy_scene", scene != null, "La scena res://enemy.tscn deve potersi istanziare"):
		return
	var enemy := scene as CharacterBody2D
	if not check("enemy_cb", enemy != null, "La radice di res://enemy.tscn deve essere un CharacterBody2D"):
		return

	var p1 := Node2D.new()
	p1.position = Vector2(0, 0)
	var p2 := Node2D.new()
	p2.position = Vector2(100, 0)
	scene.get_parent().add_child(p1)
	scene.get_parent().add_child(p2)

	enemy.global_position = Vector2(0, 0)
	enemy.waypoints = [p1, p2]

	await wait_physics_frames(20)
	check("patrol_moves", enemy.global_position.x > 1.0, "Il nemico deve iniziare a muoversi verso il punto successivo (x attuale: %.1f)" % enemy.global_position.x)

