extends "res://htd/htd_test.gd"

func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "main.tscn deve istanziarsi senza errori"):
		return
	var enemy := find_by_name(main, "Enemy") as CharacterBody2D
	if not check("enemy_found", enemy != null, "Il nodo Enemy deve essere presente"):
		return
	var player := find_by_name(main, "Player") as Node2D
	if player != null:
		player.global_position = Vector2(50, 500)

	enemy.global_position = Vector2(300, 100)
	await wait_physics_frames(40)
	check("enemy_patrols", enemy.global_position.x > 310.0, "Il nemico deve avanzare lungo la linea di pattuglia verso PointB (x = %.1f)" % enemy.global_position.x)

